/* Fundo animado: imagens selecionadas (boa qualidade em tela cheia), trocando a cada 10 segundos em ciclo. Arquivo unico: imagens e estilo incluidos. */
(function(){
  var INTERVALO=10000; /* 10 segundos por imagem */
  var IMAGENS=[
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,"
  ];
  var st=document.createElement('style');st.textContent=".bg{position:fixed;top:0;right:0;bottom:0;left:0;z-index:0;pointer-events:none;background:#000 center/cover no-repeat;opacity:0;transition:opacity 1.5s ease;--scrim:.5}\n.bg.on{opacity:1}\n.bg::after{content:\"\";position:absolute;top:0;right:0;bottom:0;left:0;background:linear-gradient(180deg,rgba(0,0,0,calc(var(--scrim) + .1)) 0%,rgba(0,0,0,var(--scrim)) 45%,rgba(0,0,0,calc(var(--scrim) + .12)) 100%)}\n:root{--card:rgba(8,8,8,.84)}\n.wrap{position:relative;z-index:1}\n.card{border-color:rgba(255,255,255,.14)}\n.tabs button:not(.on){background:rgba(8,8,8,.84)}\nheader h1,header p,.today{text-shadow:0 2px 12px rgba(0,0,0,.7)}";document.head.appendChild(st);

  /* duas camadas para fazer crossfade sem piscar */
  function camada(id){
    var e=document.getElementById(id);
    if(!e){e=document.createElement('div');e.id=id;e.className='bg';e.setAttribute('aria-hidden','true');document.body.insertBefore(e,document.body.firstChild)}
    return e;
  }
  var camadas=[camada('bg'),camada('bg2')];
  var frente=0,indice=-1,timer=null;

  function pelicula(img,el){
    var s=.5;
    try{var c=document.createElement('canvas');c.width=c.height=24;var x=c.getContext('2d');x.drawImage(img,0,0,24,24);
      var p=x.getImageData(0,0,24,24).data,t=0;for(var i=0;i<p.length;i+=4)t+=(p[i]*.299+p[i+1]*.587+p[i+2]*.114)/255;
      s=Math.min(.74,Math.max(.42,.36+t/(p.length/4)*.5))}catch(e){}
    el.style.setProperty('--scrim',s.toFixed(2));
  }

  function mostrar(i,aoTerminar){
    var img=new Image();
    img.onload=function(){
      var prox=1-frente,novo=camadas[prox],velho=camadas[frente];
      pelicula(img,novo);
      novo.style.backgroundImage='url("'+IMAGENS[i]+'")';
      novo.classList.add('on');
      if(indice>=0)velho.classList.remove('on');
      frente=prox;indice=i;
      if(aoTerminar)aoTerminar();
    };
    img.onerror=function(){if(aoTerminar)aoTerminar()};
    img.src=IMAGENS[i];
  }

  function proxima(){mostrar((indice+1)%IMAGENS.length)}

  function iniciar(){
    if(timer)return;
    timer=setInterval(proxima,INTERVALO);
  }
  function parar(){if(timer){clearInterval(timer);timer=null}}

  /* primeira imagem aparece de imediato; o ciclo comeca depois que ela carrega */
  mostrar(0,iniciar);

  /* pausa com a aba oculta e retoma ao voltar (evita trocas acumuladas) */
  document.addEventListener('visibilitychange',function(){
    if(document.hidden)parar();else if(indice>=0){parar();iniciar()}
  });
})();
